"use strict";

const fs = require("fs").promises;
const path = require("path");
const {execFile} = require("child_process");
const {promisify} = require("util");
const run = promisify(execFile);

module.exports = function(settings) {
    async function git(directory, args) {
        const result = await run("git", args, {
            cwd: directory,
            timeout: 5000,
            maxBuffer: 1024 * 1024,
            windowsHide: true,
            env: Object.assign({}, process.env, {GIT_OPTIONAL_LOCKS: "0", GIT_NO_LAZY_FETCH: "1"})
        });
        return result.stdout.trim();
    }

    async function getRoot() {
        const configured = settings.gitReposDirectory;
        if (typeof configured !== "string" || !path.isAbsolute(configured)) {
            throw new Error("gitReposDirectory must be an absolute directory in settings.js");
        }
        const root = await fs.realpath(configured);
        if (!(await fs.stat(root)).isDirectory()) {
            throw new Error("gitReposDirectory is not a directory");
        }
        return root;
    }

    async function getRepository(name, root) {
        if (typeof name !== "string" || !name || name === "." || name === ".." ||
                name.includes("/") || name.includes("\\") || name.includes("\0")) {
            throw new Error("Invalid repository name");
        }
        const directory = path.join(root, name);
        const stats = await fs.lstat(directory);
        if (!stats.isDirectory() || stats.isSymbolicLink()) {
            throw new Error("Repository is not a directory");
        }
        const realDirectory = await fs.realpath(directory);
        if (path.dirname(realDirectory) !== root) {
            throw new Error("Repository is outside gitReposDirectory");
        }
        const gitEntry = await fs.lstat(path.join(realDirectory, ".git"));
        if (gitEntry.isSymbolicLink() || (!gitEntry.isDirectory() && !gitEntry.isFile())) {
            throw new Error("Repository has no valid .git entry");
        }
        const topLevel = await git(realDirectory, ["rev-parse", "--show-toplevel"]);
        if (await fs.realpath(topLevel) !== realDirectory) {
            throw new Error("Repository is not a Git working tree");
        }
        return {name, path: realDirectory};
    }

    async function getConfiguredRepository(root) {
        try {
            return await getRepository(path.basename(root), path.dirname(root));
        } catch (error) {
            if (error.path === "git") {
                throw error;
            }
            return null;
        }
    }

    async function resolveRepository(name) {
        const root = await getRoot();
        const configuredRepository = await getConfiguredRepository(root);
        if (configuredRepository) {
            if (name !== configuredRepository.name) {
                throw new Error("Repository is not configured");
            }
            return configuredRepository;
        }
        return getRepository(name, root);
    }

    async function listRepositories() {
        const root = await getRoot();
        const configuredRepository = await getConfiguredRepository(root);
        if (configuredRepository) {
            return [configuredRepository];
        }
        const entries = await fs.readdir(root, {withFileTypes: true});
        const repositories = [];
        for (const entry of entries) {
            if (entry.isDirectory()) {
                try {
                    repositories.push(await getRepository(entry.name, root));
                } catch (error) {
                    if (error.path === "git") {
                        throw error;
                    }
                }
            }
        }
        return repositories.sort((left, right) => left.name.localeCompare(right.name));
    }

    async function listBranches(directory) {
        const output = await git(directory, ["for-each-ref", "--format=%(refname)%00%(symref)", "refs/heads", "refs/remotes"]);
        return output.split("\n").filter(Boolean).map(function(line) {
            const [ref, symref] = line.split("\0");
            if (symref || (!ref.startsWith("refs/heads/") && !ref.startsWith("refs/remotes/"))) {
                return null;
            }
            const remote = ref.startsWith("refs/remotes/");
            return {
                name: ref.slice(remote ? "refs/remotes/".length : "refs/heads/".length),
                ref,
                remote
            };
        }).filter(Boolean).sort(function(left, right) {
            return Number(left.remote) - Number(right.remote) || left.name.localeCompare(right.name);
        });
    }

    async function activeBranch(name) {
        const repository = await resolveRepository(name);
        try {
            return await git(repository.path, ["symbolic-ref", "--quiet", "HEAD"]);
        } catch (error) {
            if (error.code === 1) {
                return null;
            }
            throw error;
        }
    }

    return {listRepositories, listBranches, resolveRepository, activeBranch};
};
